import json
from src.nodes.base import BaseNode
from src.runtime.procedural_scene_assembler import get_procedural_scene_assembler
from src.runtime.asset_staging_manager import get_asset_staging_manager
from src.runtime.layout_transform_engine import get_layout_transform_engine


class HouMCPLayoutPreviewNode(BaseNode):
    name = "hou_mcp_layout_preview"
    category = "Houdini"

    def __init__(self):
        super().__init__()
        self.icon_path = "icons/houdini_icon.png"
        # [AUTO-GENERATED-PORTS-START]
        self.add_input("layout_plan_json", "string", widget_type="text", default="{}")
        self.add_input("staging_plan_json", "string", widget_type="text", default="{}")
        self.add_output("operations_preview", "list")
        self.add_output("phase_counts", "any")
        self.add_output("total_ops", "int")
        self.add_output("complexity_level", "string")
        self.add_output("camera_targets", "list")
        self.add_output("depth_layers", "any")
        self.add_output("preview_json", "string")
        # [AUTO-GENERATED-PORTS-END]

    def _empty(self):
        return {"operations_preview": [], "phase_counts": {}, "total_ops": 0, "complexity_level": "unknown", "camera_targets": [], "depth_layers": {}, "preview_json": "{}", "exec_out": True}

    async def execute(self, inputs):
        raw_layout = (inputs.get("layout_plan_json") or "{}").strip() or "{}"
        raw_staging = (inputs.get("staging_plan_json") or "{}").strip() or "{}"

        try:
            layout_plan = json.loads(raw_layout) if isinstance(raw_layout, str) else raw_layout
        except json.JSONDecodeError as exc:
            self.log_error(f"layout_plan_json is not valid JSON: {exc}")
            return self._empty()

        try:
            staging_plan = json.loads(raw_staging) if isinstance(raw_staging, str) else raw_staging
        except json.JSONDecodeError as exc:
            self.log_error(f"staging_plan_json is not valid JSON: {exc}")
            return self._empty()

        if not isinstance(layout_plan, dict) or not isinstance(staging_plan, dict):
            self.log_error("Inputs must be JSON objects.")
            return self._empty()

        assembler = get_procedural_scene_assembler()
        try:
            assembly = assembler.assemble_scene(layout_plan, staging_plan)
        except Exception as exc:
            self.log_error(f"Scene assembly preview failed: {exc}")
            return self._empty()

        operations = assembly.get("operations", [])
        phase_counts = assembly.get("phase_counts", {})
        total_ops = assembly.get("total_ops", 0)

        complexity_level = "unknown"
        try:
            staging_mgr = get_asset_staging_manager()
            complexity = staging_mgr.estimate_scene_complexity(staging_plan)
            complexity_level = complexity.get("complexity_level", "unknown")
        except Exception:
            pass

        zones = layout_plan.get("zones", {})
        depth_layers_list = layout_plan.get("depth_layers", list(zones.keys()))
        camera_targets = []
        depth_layers = {}
        try:
            engine = get_layout_transform_engine()
            camera_targets = engine.calculate_camera_focus_targets(zones, layout_plan.get("layout_rules", {}))
            depth_layers = engine.generate_depth_layers(zones, depth_layers_list)
        except Exception:
            pass

        ops_summary = [
            {"index": i, "op": op.get("op", ""), "name": op.get("name", ""), "type": op.get("type", ""), "parent": op.get("parent", "")}
            for i, op in enumerate(operations)
        ]

        preview = {
            "assembly_id": assembly.get("assembly_id", ""),
            "scene_theme": assembly.get("scene_theme", ""),
            "total_ops": total_ops,
            "phase_counts": phase_counts,
            "complexity_level": complexity_level,
            "camera_targets": camera_targets,
            "depth_layers": depth_layers,
            "ops_summary": ops_summary,
        }

        self.log_info(f"Layout preview: {total_ops} ops, {len(phase_counts)} phases, complexity={complexity_level}")

        return {
            "operations_preview": ops_summary,
            "phase_counts": phase_counts,
            "total_ops": total_ops,
            "complexity_level": complexity_level,
            "camera_targets": camera_targets,
            "depth_layers": depth_layers,
            "preview_json": json.dumps(preview, indent=2, default=str),
            "exec_out": True,
        }


def register_node():
    return HouMCPLayoutPreviewNode
